-- Loader for the pi2d reducer conformance fixtures.
--
-- The canonical event streams and the project they must reduce to live in the
-- pi2d repo: `fixtures/<case>/events.jsonl` + `fixtures/<case>/expected.json`.
-- `expected.json` is generated by `pi2d/scripts/gen-expected.ts` from the
-- TypeScript reference reducer and is committed, so both reducers (TS and the
-- authoritative Lua one in `lua/pi/web/state.lua`) are pinned to the same
-- artifact.
--
-- The checkout location is configurable through `PI2D_DIR` (defaults to the
-- sibling checkout), so the suite can run on machines with a different layout.

local M = {}

local DEFAULT_PI2D_DIR = "/home/yuez/Workspace/Neovim/pi2d"

---@class pi.web.FixtureCase
---@field name string case directory name (also the fixture's sessionId)
---@field events table[] decoded `events.jsonl` lines, in order
---@field expected table decoded `expected.json` (a SessionState)
---@field init table reducer init seed, mirroring `pi2d/scripts/gen-expected.ts`

--- pi2d checkout root (no trailing separator).
---@return string
function M.root()
    local dir = vim.env.PI2D_DIR
    if dir == nil or dir == "" then
        dir = DEFAULT_PI2D_DIR
    end
    return (dir:gsub("[/\\]+$", ""))
end

--- Fixtures directory of the pi2d checkout.
---@return string
function M.dir()
    return M.root() .. "/fixtures"
end

--- Directory entries of `dir` as `{ name, kind }` (kind may be nil).
---@param dir string
---@return { name: string, kind: string|nil }[]
local function scandir(dir)
    local out = {}
    local fd = vim.uv.fs_scandir(dir)
    if not fd then
        return out
    end
    while true do
        local name, kind = vim.uv.fs_scandir_next(fd)
        if not name then
            break
        end
        out[#out + 1] = { name = name, kind = kind }
    end
    return out
end

--- @param path string
--- @return boolean
local function is_file(path)
    local stat = vim.uv.fs_stat(path)
    return stat ~= nil and stat.type == "file"
end

--- Case names, sorted. A case is a directory with an `events.jsonl`.
---@return string[]
function M.cases()
    local dir = M.dir()
    local cases = {}
    for _, entry in ipairs(scandir(dir)) do
        if is_file(dir .. "/" .. entry.name .. "/events.jsonl") then
            cases[#cases + 1] = entry.name
        end
    end
    table.sort(cases)
    return cases
end

--- Why the fixtures cannot be used, or nil when they are present.
---@return string|nil
function M.missing_reason()
    local root = M.root()
    local dir = M.dir()
    if not vim.uv.fs_stat(dir) then
        return ("pi2d fixtures not found at %s (set PI2D_DIR to the pi2d checkout)"):format(dir)
    end
    if #M.cases() == 0 then
        return ("no fixture cases under %s (expected <case>/events.jsonl)"):format(dir)
    end
    if not is_file(root .. "/src/protocol/reducer.ts") then
        return ("%s does not look like the pi2d checkout (missing src/protocol/reducer.ts)"):format(root)
    end
    return nil
end

--- @param path string
--- @return string
local function read_file(path)
    local fd, err = io.open(path, "r")
    if not fd then
        error(("cannot read %s: %s"):format(path, tostring(err)), 0)
    end
    local raw = fd:read("*a")
    fd:close()
    return raw
end

--- Decoded `events.jsonl` for a case, in file order.
---@param name string
---@return table[]
function M.events(name)
    local events = {}
    for line in read_file(("%s/%s/events.jsonl"):format(M.dir(), name)):gmatch("[^\r\n]+") do
        if line:match("%S") then
            events[#events + 1] = vim.json.decode(line)
        end
    end
    return events
end

--- Decoded `expected.json` for a case.
---@param name string
---@return table
function M.expected(name)
    return vim.json.decode(read_file(("%s/%s/expected.json"):format(M.dir(), name)))
end

--- Reducer init seed for a case.
---
--- Mirrors the generator (`pi2d/scripts/gen-expected.ts`): `sessionId` is the
--- case name, `workspaceId` is `ws-fixture`, and `cwd` comes from the session
--- seed event the stream starts with (the reducer never patches `cwd` from
--- `pi2:session`).
---@param name string
---@param events table[] decoded events of the case
---@param expected table decoded expected state of the case
---@return table
function M.init(name, events, expected)
    local seed = events[1] and events[1].session
    local cwd = "/repo"
    if type(seed) == "table" and type(seed.cwd) == "string" then
        cwd = seed.cwd
    end
    return {
        session_id = name,
        workspace_id = expected.workspaceId,
        cwd = cwd,
    }
end

--- Load everything needed to replay a case.
---@param name string
---@return pi.web.FixtureCase
function M.load(name)
    local events = M.events(name)
    local expected = M.expected(name)
    return {
        name = name,
        events = events,
        expected = expected,
        init = M.init(name, events, expected),
    }
end

return M
